INSERT INTO public.products (product_id, name, brand, description, price, sizes, image_url, stock_quantity, category, colors_general) VALUES
('KVP010', 'Baskets Adidas Femme Gazelle Bold Trace Brown', ' Adidas', 'Découvrez l''alliance parfaite entre le style rétro et le confort moderne avec cette paire de baskets signée Adidas. Conçue pour les femmes à la recherche d''une touche d''originalité, cette chaussure séduit par sa couleur raffinée Trace Brown, rehaussée de détails Clear Pink et Earth Strata, offrant une esthétique unique et polyvalente. La matière du dessus, mêlant cuir et synthétique, assure une grande durabilité tout en conservant une allure élégante. La triple semelle plateforme en caoutchouc apporte une hauteur supplémentaire et un effet tendance, idéal pour celles qui souhaitent affirmer leur style. Les célèbres 3-Stripes et le logo doré sur le côté témoignent de l''authenticité et du savoir-faire de la marque Adidas, référence mondiale en matière de baskets. La fermeture à lacets garantit un ajustement parfait, tandis que la doublure textile et synthétique offre un confort optimal tout au long de la journée. Inspirée d''un modèle emblématique de 1971, cette basket s''adresse aux femmes qui aiment marier héritage sportif et mode contemporaine. Polyvalente, elle s''adapte aussi bien à un look décontracté qu''à une tenue plus sophistiquée. Optez pour une basket qui allie qualité, confort et design intemporel, et faites la différence à chaque pas.', '120', '["35 1/3", "36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40", "42"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_gazelle_bold_trace_brown_clear_pink_earth_strata_7.jpg', '23', 'Femme', '[''marron'', ''rose'']'),
('KVP011', 'Baskets Adidas Femme Superstar II Off White', ' Adidas', 'Découvrez l''élégance intemporelle alliée à la performance avec ces baskets signées Adidas, un choix incontournable pour toutes les femmes en quête de style et de confort au quotidien. Inspirées par l''héritage du basketball des années 70, ces chaussures se distinguent par leur design emblématique et leur qualité supérieure. La matière principale, un cuir raffiné, apporte une touche de luxe tandis que la célèbre triple bande latérale affirme un look authentique et reconnaissable. La protection offerte par l''emblématique shell-toe en caoutchouc assure une résistance optimale, idéale pour affronter les défis urbains avec assurance. À l''intérieur, la doublure textile procure douceur et bien-être à chaque pas. La semelle cupsole en caoutchouc garantit une excellente adhérence et une durabilité à toute épreuve, faisant de cette paire un allié fiable pour tous les déplacements. Le logo Trefoil sur le talon et la fermeture à lacets parachèvent ce modèle avec une note classique et sophistiquée. Parfaites pour compléter une garde-robe moderne, ces baskets s''adressent à toutes celles qui souhaitent associer allure sportive et élégance urbaine. Optez pour un modèle iconique qui traverse les tendances et sublime chaque tenue, tout en bénéficiant du savoir-faire inégalé d''Adidas.', '120', '["35 1/3", "36 2/3", "37 1/3", "38 2/3", "39 1/3", "40 2/3", "41 1/3", "36", "38", "40"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/d/adidas_women_superstar_ii_off_white_core_black_off_white_8.jpg', '13', 'Femme', '[''noir'', ''blanc'']'),
('KVP012', 'Baskets ASICS Femme JOG 100S White', ' ASICS', 'Découvrez un confort ultime et un style intemporel avec cette basket, inspirée des modèles emblématiques d''archives d''ASICS. L''empeigne en mesh respirant, composée d''au moins 75 % de matériaux recyclés, offre une ventilation optimale au quotidien. Des empiècements synthétiques assurent un soutien et une durabilité supplémentaires, tandis que la semelle intermédiaire légère en EVA garantit un amorti réactif. La semelle intérieure ORTHOLITE contribue à un confort durable et à une gestion efficace de l''humidité. Une semelle extérieure en caoutchouc avec des lignes de traction diagonales procure une excellente adhérence sur diverses surfaces. Cette basket polyvalente allie design rétro et technologie moderne, en faisant le choix idéal pour ceux qui apprécient style, confort et durabilité', '110', '["37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_women_jog_100s_whitecream_6.jpg', '6', 'Femme', '[''blanc'']'),
('KVP013', 'Baskets ASICS Femme JOG 100S Black', ' ASICS', 'Découvrez un confort ultime et un style intemporel avec cette élégante sneaker d''ASICS, inspirée par des chaussures de course classiques et réinventée avec des technologies modernes. L''empeigne en mesh respirant, fabriquée à partir de fibres recyclées, assure une ventilation optimale et une grande durabilité. La semelle en EVA moulée d''une seule pièce offre un excellent amorti, tandis que la semelle intérieure ORTHOLITE garantit un confort supplémentaire sous le pied. Grâce à la teinture innovante « spin-dye », l''environnement est préservé grâce à une réduction de 33% de la consommation d''eau. Parfaite pour un usage quotidien ou des activités sportives, cette sneaker allie avec aisance mode et fonctionnalité. Choisissez une démarche consciente, élégante et confortable grâce à la qualité ASICS', '110', '["37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_women_jog_100s_blackblack_6.jpg', '19', 'Femme', '[''noir'']'),
('KVP014', 'Baskets ASICS Men GEL-QUANTUM 360 I White', ' ASICS', 'Découvrez l''alliance parfaite entre innovation et élégance sportive avec ces baskets signées ASICS. Conçues pour les hommes exigeants, elles offrent un confort exceptionnel grâce à une technologie de pointe. Le dessus en mesh jacquard assure une excellente ventilation, maintenant vos pieds au frais même lors des activités les plus intenses. La combinaison du mesh et du synthétique garantit légèreté et durabilité, tandis que le contrefort externe au talon apporte une stabilité accrue à chaque pas. La semelle intermédiaire intègre un amorti FF BLAST PLUS, procurant un confort supérieur et un retour d''énergie optimal. La technologie GEL sur 360 degrés absorbe efficacement les chocs, idéale pour les longues journées ou les entraînements intensifs. La technologie TRUSSTIC renforce la stabilité et confère une allure dynamique à l''ensemble. Avec leur couleur blanche rehaussée de touches Diva Pink, ces baskets incarnent l''équilibre parfait entre performance et style. Optez pour l''excellence japonaise et laissez-vous séduire par une chaussure qui accompagne chaque mouvement avec assurance et modernité. Convient pour : Hommes. Marque : ASICS. Couleur : White/Diva Pink.', '180', '["41,5", "42", "42,5", "43,5", "44", "44,5", "45"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_men_gel_quantum_360_i_whitediva_pink_6.jpg', '9', 'Unisexe', '[''rose'', ''blanc'']'),
('KVP015', 'Baskets ASICS Unisexe GEL-KINETIC FLUENT White', ' ASICS', 'Cette basket élégante combine un design intemporel, inspiré des chaussures de course des années 2010, avec les dernières innovations technologiques. Grâce à la technologie avancée Scutoid GEL et à l''amorti FF BLAST PLUS ECO, chaque pas bénéficie d''un amorti ultime et d''un rebond réactif. Le système de soutien TRUSSTIC offre une stabilité supplémentaire, idéale pour un usage quotidien ou les activités sportives. La tige synthétique contient au moins 20 % de matériaux recyclés, alliant ainsi durabilité et respect de l''environnement. L''association élégante du blanc et du massepain fait de cette basket unisexe un choix parfait pour ceux qui recherchent confort, performance et style en un seul modèle', '170', '["37", "37,5", "38", "39", "39,5", "40", "40,5", "41,5", "42", "42,5", "43,5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/a/s/asics_unisex_gel_kinetic_fluent_whitemarzipan_6.jpg', '10', 'Unisexe', '[''blanc'']');